            'rating',
            'state',
            'J',
            'V',
            'D',
            'WR',
            'position',
        ],
        'ffa_ledger' => [
            'match_id',
            'event_id',
            'season_id',
            'format_id',
            'played_at',
            'winner',
            'deck_id',
            'team_id',
            'before',
            'expectation',
            'score',
            'k',
            'delta',
            'after',
        ],
        'matchups' => ['format_id', 'a', 'b', 'J', 'V', 'E', 'D', 'WR', 'performance'],
        'players' => ['player_id', 'format_id', 'JD', 'VG', 'EG', 'DG'],
        'profiles' => [
            'team_id',
            'J',
            'V',
            'E',
            'D',
            'JD',
            'VG',
            'EG',
            'DG',
            'first_n',
            'first_w',
            'second_n',
            'second_w',
            'brick_n',
            'brick',
            'brick_w',
            'lp_n',
            'lp_net',
            'lp_received',
            'turn_n',
            'turn_sum',
            'duration_n',
            'duration_sum',
            'fastest',
            'fewest_turns',
        ],
        'pending' => ['match_id', 'reason'],
    ];
    if (!isset($fields[$collection])) {
        throw new InvalidArgumentException('Coleccion estadistica no exportable.');
    }
    $rows = [array_merge($fields[$collection], ['corte', 'version', 'estado_corte'])];
    foreach ($data[$collection] ?? [] as $entry) {
        $row = [];
        foreach ($fields[$collection] as $field) {
            $value = $entry[$field] ?? 'N/D';
            $row[] = is_array($value)
                ? json_encode($value, JSON_UNESCAPED_UNICODE | JSON_PRESERVE_ZERO_FRACTION)
                : $value;
        }
        $rows[] = array_merge($row, [
            $data['cutoff'] ?? 'N/D',
            $data['version'] ?? YGO_STATS_VERSION,
            $data['status'] ?? 'PENDIENTE',
        ]);
    }
    return $rows;
}

ygo_stats_filter.original:
function ygo_stats_filter(array $matches, array $filters): array
{
    $allowed = [
        'event_id',
        'season_id',
        'division_id',
        'phase',
        'event_type',
        'team_id',
        'deck_id',
        'player_id',
        'judge',
        'venue',
        'from',
        'to',
        'format_id',
    ];
    foreach (array_keys($filters) as $key) {
        if (!in_array($key, $allowed, true)) {
            throw new InvalidArgumentException('Filtro no soportado: ' . $key);
        }
    }
    foreach (['from', 'to'] as $key) {
        if (!empty($filters[$key])) {
            $d = DateTimeImmutable::createFromFormat('!Y-m-d', $filters[$key]);
            if (!$d || $d->format('Y-m-d') !== $filters[$key]) {
                throw new InvalidArgumentException('Fecha de filtro invalida.');
            }
        }
    }
    return array_values(
        array_filter($matches, static function ($m) use ($filters) {
            foreach ($filters as $key => $value) {
                if ($value === '') {
                    continue;
                }
                if ($key === 'from' && substr($m['played_at'], 0, 10) < $value) {
                    return false;
                }
                if ($key === 'to' && substr($m['played_at'], 0, 10) > $value) {
                    return false;
                }
                if (in_array($key, ['from', 'to'], true)) {
                    continue;
                }
                if (in_array($key, ['team_id', 'deck_id'], true)) {
                    $ids = [
                        (int) ($m[str_replace('_id', '_a_id', $key)] ?? 0),
                        (int) ($m[str_replace('_id', '_b_id', $key)] ?? 0),
                    ];
                    foreach (
                        array_merge(
                            $m['participants_a'] ?? [],
                            $m['participants_b'] ?? [],
                            $m['players'] ?? [],
                        )
                        as $p
                    ) {
                        $ids[] = (int) $p[$key];
                    }
                    if (!in_array((int) $value, $ids, true)) {
                        return false;
                    }
                    continue;
                }
                if ($key === 'player_id') {
                    $found = false;
                    foreach ($m['duels'] ?? [] as $d) {
                        if (
                            in_array(
                                (int) $value,
                                [(int) ($d['player_a_id'] ?? 0), (int) ($d['player_b_id'] ?? 0)],
                                true,
                            )
                        ) {
                            $found = true;
                        }
                    }
                    if (!$found) {
                        return false;
                    }
                    continue;
                }
                if (!array_key_exists($key, $m) || (string) $m[$key] !== $value) {
                    return false;
                }
            }
            return true;
        }),
    );
}

ygo_stats_group_reason.original:
function ygo_stats_group_reason(array $m): ?string
{
    if (
        ($m['confirmed'] ?? false) !== true ||
        !in_array($m['result'] ?? '', ['A', 'B', 'E'], true)
    ) {
        return 'Resultado Tag no confirmado';
    }
    if (empty($m['competitive']) || !empty($m['friendly'])) {
        return 'Tag no puntuable';
    }
    if (
        empty($m['played_at']) ||
        empty($m['format_id']) ||
        empty($m['match_id']) ||
        empty($m['duels'])
    ) {
        return 'Tag sin evidencia de juego';
    }
    $teams = [];
    $decks = [];
    foreach (['participants_a', 'participants_b'] as $side) {
        if (count($m[$side] ?? []) !== 2) {
            return 'Alineacion Tag incompleta';
        }
        foreach ($m[$side] as $p) {
            if (
                ($p['quality'] ?? '') !== 'CONFIRMED_AT_ROSTER_FREEZE' ||
                empty($p['team_id']) ||
                empty($p['deck_id']) ||
                ($p['format_id'] ?? '') !== $m['format_id']
            ) {
                return 'Identidad historica Tag no confirmada';
            }
            if (isset($teams[$p['team_id']]) || isset($decks[$p['deck_id']])) {
                return 'Identidad competitiva repetida en la mesa Tag';
            }
            $teams[$p['team_id']] = true;
            $decks[$p['deck_id']] = true;
        }
    }
    return null;
}

ygo_stats_tag_accumulate.original:
function ygo_stats_tag_accumulate(
    array &$r,
    array $m,
    array $person,
    array $opponents,
    bool $won,
    bool $draw,
): void {
    $score = $won ? 1.0 : ($draw ? 0.5 : 0.0);
    $r['J']++;
    $r[$won ? 'V' : ($draw ? 'E' : 'D')]++;
    $r['streak'] = $won ? $r['streak'] + 1 : 0;
    $r['best_streak'] = max($r['best_streak'], $r['streak']);
    foreach ($opponents as $o) {
        $r['opponents'][$o['team_id']] = true;
        if ($won) {
            $r['rivals_beaten'][$o['team_id']] = true;
        }
    }
    if (
        $r['last_at'] !== null &&
        (new DateTimeImmutable($r['last_at']))->diff(new DateTimeImmutable($m['played_at']))->days >
            90
    ) {
        $r['reactivation'] = 0;
    }
    $r['reactivation'] = min(3, $r['reactivation'] + 1);
    $r['last_at'] = $m['played_at'];
    $r['recent'][] = $score;
    $r['evidence'][] = $m['source_key'];
    $r['tag_matches'] = ($r['tag_matches'] ?? 0) + 1;
    $r['shared_duels'] = ($r['shared_duels'] ?? 0) + count($m['duels']);
    // Shared duel wins are not individual duel wins, LP damage or flawless evidence.
    if ($won) {
        $r['events_won_match'][$m['event_id'] ?? 0] = true;
        $r['formats'][$m['format_id']] = true;
        $r['format_moments'][$m['format_id']] ??= [
            'sports_effective_at' => $m['played_at'],
            'match_id' => $m['match_id'],
        ];
    }
}

