ygo_stats_apply_tag.original:
function ygo_stats_apply_tag(
    array $m,
    array $policy,
    array &$global,
    array &$profiles,
    array &$ledger,
): void {
    $format = $m['format_id'];
    $left = $m['participants_a'];
    $right = $m['participants_b'];
    $all = array_merge($left, $right);
    $before = [];
    foreach ($all as $p) {
        $key = $p['team_id'] . ':' . $format;
        $global[$key] ??= ygo_stats_metric($p['team_id'], $p['deck_id'], $format);
        $global[$key]['deck_id'] = $p['deck_id'];
        $before[$p['team_id']] = $global[$key]['rating'];
    }
    $k = (float) $policy['k_mapping'][$m['ranking_impact']];
    $score = $m['result'] === 'A' ? 1.0 : ($m['result'] === 'E' ? 0.5 : 0.0);
    $change = ygo_stats_tag_elo(
        array_map(fn($p) => $before[$p['team_id']], $left),
        array_map(fn($p) => $before[$p['team_id']], $right),
        $score,
        $k,
    );
    $changes = [];
    foreach (
        [
            ['A', $left, $right, $change['delta_a'], $change['before_b']],
            ['B', $right, $left, $change['delta_b'], $change['before_a']],
        ]
        as [$side, $members, $opponents, $delta, $rivalMean]
    ) {
        foreach ($members as $p) {
            $key = $p['team_id'] . ':' . $format;
            $profile = $p['team_id'];
            $profiles[$profile] ??= ygo_stats_metric($profile, $p['deck_id'], '*');
            $won = $m['result'] === $side;
            $draw = $m['result'] === 'E';
            ygo_stats_tag_accumulate($global[$key], $m, $p, $opponents, $won, $draw);
            ygo_stats_tag_accumulate($profiles[$profile], $m, $p, $opponents, $won, $draw);
            $global[$key]['rival_pre_sum'] += $rivalMean;
            $global[$key]['rating'] = $before[$profile] + $delta;
            foreach (ygo_stats_achievements($profiles[$profile]) as $a) {
                if ($a['status'] === 'DESBLOQUEADO') {
                    $profiles[$profile]['achievement_moments'][$a['code']] ??= [
                        'sports_effective_at' => $m['played_at'],
                        'match_id' => $m['match_id'],
                    ];
                }
            }
            $changes[] = [
                'team_id' => $profile,
                'deck_id' => $p['deck_id'],
                'side' => $side,
                'before' => $before[$profile],
                'delta' => $delta,
                'after' => $before[$profile] + $delta,
                'rival_mean' => $rivalMean,
            ];
        }
    }
    $ledger[] = array_merge($change, [
        'kind' => 'tag',
        'source_key' => $m['source_key'],
        'match_id' => $m['match_id'],
        'format_id' => $format,
        'season_id' => $m['season_id'],
        'event_id' => $m['event_id'],
        'played_at' => $m['played_at'],
        'result' => $m['result'],
        'team_a_id' => null,
        'team_b_id' => null,
        'deck_a_id' => null,
        'deck_b_id' => null,
        'participants' => $changes,
        'source_version' => $m['source_version'],
        'algorithm_version' => YGO_STATS_VERSION,
    ]);
}

