            $teamMetrics[$r['team_id']] ?? $r,
            $events,
            $honors,
            array_values($seen),
        );
        $r['achievements'][38]['name'] = 'Primera victoria en ' . $r['format_id'];
        $r['achievements'][38]['progress'] = $r['V'];
        $r['achievements'][38]['status'] = $r['V'] > 0 ? 'DESBLOQUEADO' : 'BLOQUEADO';
